36	Status Version::Load(const std::string &path, Version *version) {
37	  std::ifstream ifs;
38	  ailego::FileHelper::OpenIfstream(ifs, path, std::ios::binary);
39	  if (!ifs.is_open()) {
40	    LOG_ERROR("Failed to open file: %s", path.c_str());
41	    return Status::InternalError("Failed to open file");
42	  }
43	
44	  proto::Manifest manifest;
45	
46	  if (!manifest.ParseFromIstream(&ifs)) {
47	    LOG_ERROR("Failed to parse manifest from file: %s", path.c_str());
48	    return Status::InternalError("Failed to parse manifest");
49	  }
50	
51	  CollectionSchema::Ptr schema = ProtoConverter::FromPb(manifest.schema());
52	  version->set_schema(*schema);
53	
54	  version->set_enable_mmap(manifest.enable_mmap());
55	
56	  for (int i = 0; i < manifest.persisted_segment_metas_size(); ++i) {
57	    SegmentMeta::Ptr meta =
58	        ProtoConverter::FromPb(manifest.persisted_segment_metas(i));
59	    version->add_persisted_segment_meta(meta);
60	  }
61	
62	  if (manifest.has_writing_segment_meta()) {
63	    SegmentMeta::Ptr meta =
64	        ProtoConverter::FromPb(manifest.writing_segment_meta());
65	    version->reset_writing_segment_meta(meta);
66	  }
67	
68	  version->set_id_map_path_suffix(manifest.id_map_path_suffix());
69	  version->set_delete_snapshot_path_suffix(
70	      manifest.delete_snapshot_path_suffix());
71	
72	  version->set_next_segment_id(manifest.next_segment_id());
73	
74	  return Status::OK();
75	}
